<div class="section-actions"><p class="muted">Keep each organization's people, systems and procedures together.</p><?php if($actor->role==='administrator'): ?><div><a class="text-link" href="<?= $link('/organizations?trash='.($trash?'0':'1')) ?>"><?= $trash?'Active organizations':'Archived organizations' ?></a> <a class="button" href="<?= $link('/organizations/new') ?>">+ New organization</a></div><?php endif; ?></div>
<?php if(!$organizations): ?><div class="empty-state card"><h2><?= $trash?'No archived organizations':'Your documentation starts here' ?></h2><p><?= $actor->role==='administrator'?'Create your first organization to add locations, contacts, assets and articles.':'An administrator can assign organizations to your account.' ?></p></div><?php endif; ?>
<div class="organization-grid"><?php foreach($organizations as $o): ?><article class="card org-card"><div class="org-avatar"><?= $e(mb_strtoupper(mb_substr($o['name'],0,1))) ?></div><h2><?php if(!$trash): ?><a href="<?= $link('/organizations/'.$o['id']) ?>"><?= $e($o['name']) ?></a><?php else: ?><?= $e($o['name']) ?><?php endif; ?></h2><p class="muted"><?= $e(mb_substr($o['description']??'',0,160)) ?></p><?php if($trash): ?><form method="post" action="<?= $link('/organizations/'.$o['id'].'/restore') ?>"><?= $csrf ?><button class="button secondary">Restore organization</button></form><?php else: ?><a class="text-link" href="<?= $link('/organizations/'.$o['id']) ?>">Open documentation →</a><?php endif; ?></article><?php endforeach; ?></div>
